import Foundation

// The fingerprint's window and FFT twiddle factors exactly as the JavaScript
// engine computed them. V8's Math.cos and Math.sin differ from macOS's in the
// last bit for about one value in twenty here; using V8's values keeps new
// fingerprints bit for bit like the ones already on disk. Little-endian
// doubles, base64 (generated once with Node from the formulas in the comments).
enum FFTTables {
  /// 0.5 - 0.5 * cos(2πi / 2047), i = 0..<2048
  static let hann = decode(hannData)
  /// cos(2πi / 2048), i = 0..<1024
  static let cos = decode(cosData)
  /// -sin(2πi / 2048), i = 0..<1024
  static let sin = decode(sinData)

  private static func decode(_ parts: [String]) -> [Double] {
    let data = Data(base64Encoded: parts.joined())!
    return data.withUnsafeBytes { raw in
      (0..<data.count / 8).map { Double(bitPattern: UInt64(littleEndian: raw.loadUnaligned(fromByteOffset: $0 * 8, as: UInt64.self))) }
    }
  }

